{
 "research_concepts": ["player absence", "offensive reorganization", "reorganization relative to baseline L", "change in points per possession (PPP)", "play-type possession records", "starter absence and rotation intervals"],
 "methodological_questions": [
  "How is offensive reorganization measured, and what is L (the baseline against which it is measured)?",
  "Is the reorganization measure computed independently of the PPP outcome, or derived from the same possessions?",
  "Does the spell-level sample of 148 have enough power to detect a plausible effect, given the stated MDE placeholder (rho not specified)?",
  "Are play-type labels accurate enough to support a reorganization measure?",
  "How are regression to the mean, lineup and opponent confounding, and playoff/regular-season differences handled?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-088",
   "status_as_recorded": "supported",
   "finding": "Connector absence displaced team offensive identity (D_A) more than usage-matched non-organizer absence: unmatched 0.2020 vs 0.1021 (t=5.97, p=2.87e-08); usage-matched paired dD_A +0.1151, P(conn>ctrl)=81.2%, n=96; vs terminal +0.0777, p=0.0261, n=25. Recorded limitation: small_sample; mechanical_floor risk."
  },
  {
   "id": "FAM:SF-APPS-025",
   "status_as_recorded": "untestable",
   "finding": "Adapt-vs-continue matched-pair overall-offense excess (post-hoc). Caliper 0.10: group A excess +0.076 [+0.068,+0.084] n=3421; group B excess +0.014 [-0.019,+0.046] n=255 (p=0.386); gap B-A = -0.062. Group B CIs include 0 at all calipers except 0.15. Recorded as a reconstructed post-hoc cohort, not a validated sample."
  },
  {
   "id": "FAM:SF-CHT-052",
   "status_as_recorded": "inconclusive",
   "finding": "Play-type replacement similarity vs absorb/cascade: mean similarity ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap) = -0.19 (wrong-signed). Recorded failure type B_powered_null, but the sample and power were not recorded; verdict null."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Play-type label accuracy audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most play types have PPP above benchmark band; MIA identity checks fail. Verdict tool_eval_fail."
  },
  {
   "id": "FAM:SF38",
   "status_as_recorded": "inconclusive",
   "finding": "Defensive in-game adaptation to repeated play type. League-wide within-game slope -0.0019 PPP/exposure (SE 0.0019); across-game +0.0004 (SE 0.0015). Only PULL_UP survives Holm (B -0.0243, SE 0.0061, holm 0.0004). Team-trait split-half r +0.008; season-to-season +0.037. Limited by insufficient_exposure, label error, low measurement reliability."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Defensive scheme change inferred from labels: within-game change 61.0%, cross-game change 67.7%; transition matrices near-uniform. The record states the inferred label cannot separate real defensive adjustment from offense executing differently, and that near-uniform matrices are consistent with label noise."
  },
  {
   "id": "FAM:SF-CHT-063",
   "status_as_recorded": "artifact",
   "finding": "BEST-vs-continue gap after a slump was +0.248 (SE 0.009), the same without a slump (+0.239) and under a fixed CUT-heavy ranking (+0.238). The recorded verdict is artifact_found, with the gap attributed to construction rather than to the slump."
  },
  {
   "id": "FAM:SF-PAP-008",
   "status_as_recorded": "inconclusive",
   "finding": "Route entropy: shaper presence on non-focal play-type entropy d = -0.0455 (n_ts=80); organizer +0.0115. No CI reported; the paper reads this as rebalancing rather than expansion. Verdict null."
  },
  {
   "id": "FAM:SF-APPS-071",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Memoryless Monte Carlo generative check: uncalibrated PPP std 1.149 vs simulated 1.152; lag-1 scoring autocorrelation real -0.0022 vs simulated +0.0029. Described as an existence proof, not independent evidence."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPS-025",
   "what_failed": "Matched-pair comparison of adapt vs continue groups on overall-offense excess, using a post-hoc reconstructed group B",
   "why": "Group B CI includes 0 at the primary caliper (p=0.386, n=255 pairs / 242 games); the group is post-hoc and not a validated successful-adaptation sample; recorded as A_unanswerable."
  },
  {
   "id": "FAM:SF-CHT-052",
   "what_failed": "Using play-type replacement similarity to separate absorption from cascade after a player sits",
   "why": "Similarity did not separate the groups and the sign was wrong; recorded as B_powered_null, though sample size and power were not recorded and label error is flagged."
  },
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Inferred play-type labels as a basis for adaptation findings",
   "why": "Audit failed: OTHER share 20.2%, foul-draw rates far below benchmark, PPP above band for most types, identity checks failing; recorded as C_artifact and tool_eval_fail."
  },
  {
   "id": "FAM:SF38",
   "what_failed": "Within-game exposure slope of PPP to repeated play type",
   "why": "Effect is near zero overall; only one play type survives correction; team-trait reliability is low; limited by insufficient exposure and label error."
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferred defensive scheme-change transitions from play-type labels",
   "why": "Label cannot separate defensive adjustment from offensive execution; near-uniform transitions consistent with label noise; recorded as A_unanswerable."
  }
 ],
 "evidence_establishes": [
  "Connector absence, as a player-identity measure, changes team offensive identity more than usage-matched absence of non-organizers (FAM:SF-APPS-088, supported, n=96 matched pairs). This is an identity-displacement result, not a PPP-change result.",
  "Play-type labels from this pipeline have documented accuracy failures (FAM:SF-APPM-014), so any reorganization measure built on them inherits label error.",
  "Earlier attempts to link play-type or similarity-based reorganization to outcomes (FAM:SF-CHT-052, FAM:SF-APPS-025, FAM:SF38, FAM:SF-PAP-008) returned null, untestable, or inconclusive results, with several limited by power, label quality, or post-hoc cohort construction.",
  "Small-sample and label-quality caveats recur across the retrieved families, so the group-level question has not been answered by this project."
 ],
 "evidence_does_not_establish": [
  "None of the returned records measures offensive reorganization relative to a baseline L, or regresses change in PPP on such a measure after player absence.",
  "No returned record reports a PPP-change outcome for absence spells; SF-APPS-088 reports identity displacement, not scoring change.",
  "Whether a reorganization effect exists at the 148-spell scale, and at what magnitude, is not established.",
  "The meaning of L and the definition of reorganization are not stated in the retrieved evidence or the task statement."
 ],
 "own_inferences": [
  "The research question as posed is underspecified: L, the reorganization metric, the PPP-change window, and the absence definition are not defined, so it cannot be tested as written.",
  "A reorganization measure built from play-type possessions and PPP change measured on the same possessions would create outcome-derived labelling and leakage risk.",
  "With 148 spells, power to detect a modest effect is likely low unless the expected effect is large; the MDE is recorded only as a placeholder with rho unspecified.",
  "Unit counts are ambiguous: n=986 and 148 spells are not clearly linked; the 148-spell figure is the likely effective sample."
 ],
 "uncertainties": [
  "Definition of L and the reorganization metric are missing.",
  "MDE value and the rho parameter are unspecified; power cannot be computed from the stated information.",
  "Relationship between n=986 and n=148 spells is not stated.",
  "Partial 2025-26 data (regular season and playoffs) is not yet complete on the decision date; including it would change the sample.",
  "Label accuracy for the 2022-23 to 2025-26 play-type files has not been validated beyond the failed audit in FAM:SF-APPM-014.",
  "Whether the retrieval set is complete for this project's earlier work is unknown."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "Retrieved evidence shows that play-type-based similarity and reorganization-style measures have produced null, untestable, or artifact results, and that play-type labels fail audit (FAM:SF-CHT-052, FAM:SF-APPS-025, FAM:SF-APPM-014, FAM:SF38, FAM:SF-APPA-005). Together with the undefined L and the 148-spell sample, this moved the decision from a provisional proceed to do_not_proceed as posed. A test is still possible if the measure and L are fixed in advance and labels are validated."
 },
 "testability": {
  "p_testable": 0.3,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "Play-type labels failed audit (OTHER 20.2%, foul-draw 1.7% vs 14-22%); reorganization measured from them is unreliable."
   },
   {
    "code": "OUTCOME_DERIVED_LABEL",
    "text": "If reorganization and PPP change are computed from the same possessions, the predictor partly encodes the outcome."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "148 spells with an unspecified MDE (rho) gives unknown and probably low power to detect a modest effect."
   },
   {
    "code": "MEASURE_RELIABILITY",
    "text": "Team-trait and season-to-season reliability of play-type measures is low in related work (split-half r +0.008, season-to-season +0.037 in FAM:SF38)."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": ["FAM:SF-APPS-088", "FAM:SF-APPS-025", "FAM:SF-CHT-052", "FAM:SF38", "FAM:SF-APPM-014", "FAM:SF-APPA-005"],
  "summary": "No retrieved study measures offensive reorganization relative to L and regresses PPP change on it. Related work covers identity displacement after connector absence (supported, FAM:SF-APPS-088), play-type similarity and adaptation (null, untestable, or inconclusive: FAM:SF-CHT-052, FAM:SF-APPS-025, FAM:SF38), and label audits that failed (FAM:SF-APPM-014). The question is therefore not answered, but adjacent work exists."
 },
 "risks": [
  {"code": "LABEL_ERROR", "text": "Play-type labels fail audit; OTHER share and foul-draw rates are far from benchmark; reorganization from these labels is biased."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "Reorganization and PPP change may be built from the same possessions, so the predictor leaks the outcome."},
  {"code": "LEAKAGE_LOOKAHEAD", "text": "Using post-absence possessions to define the reorganization baseline L, or to select spells, leaks future information into the predictor."},
  {"code": "SAMPLE_SIZE_POWER", "text": "148 spells and an unspecified MDE; power to detect a modest effect is probably low."},
  {"code": "RTM_SELECTION", "text": "Spells selected because of an extreme PPP drop or reorganization spike will regress toward the mean, inflating apparent effects."},
  {"code": "CONFOUNDING", "text": "Opponent quality, lineup, rest, usage, injury status and garbage time may drive both reorganization and PPP change."},
  {"code": "EXPOSURE_SPARSITY", "text": "Some players or teams have few absence spells, so team-level estimates are unstable."},
  {"code": "MEASURE_RELIABILITY", "text": "Related families show low reliability of play-type and team-trait measures."},
  {"code": "BASE_RATE", "text": "Frequency of absences and the baseline PPP differ across seasons and playoffs, so pooling may mix regimes."},
  {"code": "DRIFT_NONSTATIONARITY", "text": "Pooling 2022-23 through 2025-26 may mix rule and pace changes across seasons."},
  {"code": "PLACEBO_DEPENDENCE", "text": "A post-hoc cohort construction, as in FAM:SF-APPS-025, could produce an apparent effect that depends on the placebo or caliper choice."},
  {"code": "MULTIPLE_TESTING", "text": "Multiple measures of reorganization, windows, and L values invite selective reporting."},
  {"code": "IMPLEMENTATION_BUG", "text": "Joining play-by-play, substitution intervals, and derived play-type records across sources could misalign possessions."}
 ],
 "predicted_outcome": {
  "supported": 0.12,
  "rejected": 0.2,
  "untestable": 0.28,
  "artifact": 0.2,
  "uncertain": 0.2
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Among player-absence spells, the association between offensive reorganization relative to a pre-specified baseline L and the change in PPP from the pre-absence to the post-absence window. The primary parameter is the regression slope of PPP change on the standardized reorganization index.",
  "unit": "Player-absence spell (one row per spell, with team-level possessions aggregated within the spell window).",
  "sample": "Spells from 2022-23 to 2025-26 regular seasons only, with 2025-26 limited to the complete regular season (from 2026-04-13). Playoffs and partial 2025-26 data are excluded from the primary analysis and reported separately. Reconcile n=986 versus 148 spells before analysis.",
  "power": "Not computable from the stated information. Before analysis, fix rho and the MDE, then compute power for the spell count. If power is below 0.8 at the pre-specified MDE, report the result as inconclusive rather than null.",
  "controls": "Opponent defensive rating, lineup and starter identity, minutes and usage of the absent player, rest days, home/away, garbage-time filter, season fixed effects, and team fixed effects. Reorganization is computed from a separate possession set from the PPP outcome (split-sample or time-disjoint windows) to avoid outcome-derived labels.",
  "falsification": "Placebo absences of low-impact bench players; pre-absence window as a placebo outcome; a shuffled reorganization index within team-season; and a label-validation check that the play-type audit passes its thresholds before the measure is used.",
  "multiplicity": "One primary test (slope of PPP change on the pre-registered reorganization index at the pre-registered L). Secondary measures are reported with Holm correction; any alternative L or window is exploratory only.",
  "decision_rule": "Supported if the primary slope's 95% CI excludes zero in the pre-registered direction, the placebo tests show no effect, and power at the MDE is at least 0.8. Rejected if the CI is within the pre-registered null range and power is adequate. Otherwise report as uncertain.",
  "data_version": "Lock the 2026-11-01 snapshot for all files; record the 2025-26 regular-season completion status; log play-type audit results before analysis."
 }
}

